package m

import "testing"

func TestParseBad(t *testing.T) {
	if _, err := Parse("x"); err == nil {
		t.Fatal("want error")
	}
	if n, err := Parse("7"); err != nil || n != 7 {
		t.Fatal("want 7")
	}
}
